// The profile map of wine-style-profiles (D1, D9, BR2.1-BR2.17): the profile
// and the window of every combination (denomination, type, qualifier) of the
// study, generated by tool/build_profile_map.dart from the study database
// into generated/profile_map.g.dart. Parsed once, on first use (NFR3).

import 'generated/profile_map.g.dart';
import 'models.dart';

/// How the window of a combination was decided (ENT-105 `windowSource`
/// reduced to the map's outcomes).
enum MapEstimate {
  /// The profile's numbers or a kept legacy window.
  profiled,

  /// The style is not clear: today's values as an indicative estimate.
  indicative,

  /// "To estimate": no window (BR2.9).
  none,
}

/// One combination of the generated map.
class ProfileMapEntry {
  const ProfileMapEntry({
    required this.id,
    required this.wineType,
    required this.profile,
    required this.step,
    required this.estimate,
    required this.anchor,
    required this.unit,
    required this.start,
    required this.peak,
    required this.end,
    required this.styleToConfirm,
    required this.rowMakesType,
    required this.typeCorrected,
    required this.presetLevel,
  });

  /// `key:base:type`, `key:otherType:type` or `key:qualifier:qualifier`.
  final String id;

  /// Type after the corrections (BR2.12); `null` for a generated row
  /// without a real type.
  final WineType? wineType;
  final StyleProfile profile;

  /// Step of the precedence that decided the window (1-4, BR2.1).
  final int step;
  final MapEstimate estimate;
  final AgingAnchor? anchor;
  final WindowUnit? unit;
  final int? start;
  final int? peak;
  final int? end;
  final bool styleToConfirm;

  /// False when the corrected row does not make the type of the id: the
  /// estimate uses the type's profile (BR2.12).
  final bool rowMakesType;
  final bool typeCorrected;

  /// Level the preselection proposes (BR4.3).
  final WineLevel presetLevel;

  /// True when the window keeps today's values in years (steps 2 and the
  /// indicative rows), so it is not the profile's own numbers.
  bool get keepsLegacyWindow =>
      estimate != MapEstimate.none &&
      (start != profile.start || peak != profile.peak || end != profile.end);
}

/// Parses one row of [profileMapRows]:
/// `id|type|profile|step|estimate|anchor|unit|start|peak|end|flags|level`.
/// Returns `null` for a malformed row.
ProfileMapEntry? parseProfileMapRow(String row) {
  final parts = row.split('|');
  if (parts.length != 12) return null;
  final [
    id,
    type,
    profileId,
    step,
    estimate,
    anchor,
    unit,
    start,
    peak,
    end,
    flags,
    level,
  ] = parts;
  final profile = StyleProfile.tryParse(profileId);
  final stepValue = int.tryParse(step);
  final estimateValue = _byName(MapEstimate.values, estimate);
  final levelValue = WineLevel.tryParse(level);
  if (id.isEmpty ||
      profile == null ||
      stepValue == null ||
      estimateValue == null ||
      levelValue == null) {
    return null;
  }
  return ProfileMapEntry(
    id: id,
    wineType: type.isEmpty ? null : WineType.tryParse(type),
    profile: profile,
    step: stepValue,
    estimate: estimateValue,
    anchor: _byName(AgingAnchor.values, anchor),
    unit: _byName(WindowUnit.values, unit),
    start: int.tryParse(start),
    peak: int.tryParse(peak),
    end: int.tryParse(end),
    styleToConfirm: flags.contains('c'),
    rowMakesType: !flags.contains('n'),
    typeCorrected: flags.contains('t'),
    presetLevel: levelValue,
  );
}

T? _byName<T extends Enum>(List<T> values, String name) {
  for (final value in values) {
    if (value.name == name) return value;
  }
  return null;
}

/// Every combination keyed by id, built once.
final Map<String, ProfileMapEntry> profileMap = Map.unmodifiable(
  _parseAll(profileMapRows),
);

Map<String, ProfileMapEntry> _parseAll(List<String> rows) {
  final map = <String, ProfileMapEntry>{};
  for (final row in rows) {
    final entry = parseProfileMapRow(row);
    if (entry != null) map[entry.id] = entry;
  }
  return map;
}

/// The id of the combination of the row [key] for [type] (the row's
/// [mainType] or another type) with [qualifier] (main type only).
String profileMapIdOf(
  String key,
  WineType mainType,
  WineType type,
  Qualifier? qualifier,
) {
  if (type != mainType) return '$key:otherType:${type.name}';
  if (qualifier != null) return '$key:qualifier:${qualifier.name}';
  return '$key:base:${type.name}';
}
